// Daily Safe Quota & Normalizer
// Limits daily outreach to prevent WhatsApp number flag/ban
const MAX_DAILY_OUTREACH = 25; // Safe daily limit for outreach

const rawItems = $input.all();
if (!rawItems || rawItems.length === 0) {
  return [];
}

// Slice to process only up to MAX_DAILY_OUTREACH leads per day
const batch = rawItems.slice(0, MAX_DAILY_OUTREACH);

return batch.map((item, index) => {
  const row = item.json;

  // Extract fields
  const businessName = (row['Business Name'] || row['Company'] || row['Name'] || 'Valued Builder').trim();
  const city = (row['City'] || row['Location'] || 'your area').trim();

  // Clean Phone to E.164
  let rawPhone = (row['Phone'] || row['WhatsApp'] || row['Mobile'] || '').toString().replace(/[^0-9+]/g, '');
  if (rawPhone && !rawPhone.startsWith('+')) {
    if (rawPhone.length === 10) rawPhone = '+91' + rawPhone;
    else if (rawPhone.length === 12 && rawPhone.startsWith('91')) rawPhone = '+' + rawPhone;
  }

  const email = (row['Email'] || '').trim().toLowerCase();
  const website = (row['Website'] || '').trim();

  // Check if real custom domain vs directory/social
  const isDirectoryOrSocial = /(facebook\.com|instagram\.com|indiamart\.com|justdial\.com|linkedin\.com)/i.test(website);
  const hasDedicatedWebsite = Boolean(website && website.length > 8 && !isDirectoryOrSocial);

  return {
    json: {
      rowIndex: index + 1,
      businessName,
      city,
      phone: rawPhone,
      email,
      rawWebsite: website,
      hasDedicatedWebsite,
      originalRow: row
    }
  };
});

const lead = $json;
const name = lead.businessName;
const location = lead.city;

// Spintax / Random variation to prevent identical message hash detection
const openers = [
  `Hi ${name}, came across your construction work in ${location} and noticed you don't have a dedicated website for your completed projects.`,
  `Hello ${name} Team, was reviewing quality turnkey house builders in ${location}. I couldn't find an official website showcasing your elevations and floor plans.`,
  `Hi ${name}, hope your current building projects in ${location} are going well! Noticed you showcase work mostly via WhatsApp without a modern web portfolio.`
];
const opener = openers[Math.floor(Math.random() * openers.length)];

const whatsappMessage = 
  `${opener}\n\n` +
  `Most prospective homeowners compare 3-4 builders online before initiating quotation enquiries. Without an interactive portfolio, they often perceive you as a labor contractor rather than a premium turnkey builder.\n\n` +
  `We help independent builders launch a turnkey digital system — with 3D house visualizers, 360° virtual site tours, and a 24/7 WhatsApp AI qualification assistant.\n\n` +
  `Would you be open to seeing a 2-minute concept design we prepared for builders in ${location}?`;

const emailSubject = `Project showcase & quotation system for ${name}`;
const emailBody = 
  `Hi ${name} Team,\n\n` +
  `I noticed your construction projects in ${location}. Your workmanship is strong, but you currently lack a dedicated modern website to showcase your portfolio, elevation designs, and completed handovers.\n\n` +
  `We build custom digital systems for independent house contractors that include:\n` +
  `1. Premium Portfolio: 3D elevations & 360° virtual site walkthroughs\n` +
  `2. Smart Cost & BOQ Estimator: Pre-qualifies homeowner budget and plot dimensions\n` +
  `3. WhatsApp AI Assistant: Instantly books site inspections 24/7\n\n` +
  `Would you be open to a 2-minute concept walkthrough tailored for ${name}?\n\n` +
  `Best regards,\nSuresh Kumar\nBuilder Digital Experience & Enquiry System™`;

return [{
  json: {
    ...lead,
    segment: "Segment A - No Website",
    whatsappMessage,
    emailSubject,
    emailBody
  }
}];

const lead = $('Loop Over Leads (1 by 1)').first().json;
const probe = $input.first().json;
const isError = Boolean(probe.error || !probe);

const name = lead.businessName;
const location = lead.city;

let observation = "your website does not have an instant WhatsApp quotation button or 360° virtual tour, leading mobile visitors to drop off";
if (isError) {
  observation = "your website domain appears to be inaccessible or returning errors, resulting in lost homeowner enquiries";
}

// Anti-ban randomized variation
const openers = [
  `Hi ${name}, came across your construction projects and checked out your website (${lead.rawWebsite}).`,
  `Hello ${name} Team, was reviewing your house construction work in ${location} via your website (${lead.rawWebsite}).`
];
const opener = openers[Math.floor(Math.random() * openers.length)];

const whatsappMessage = 
  `${opener}\n\n` +
  `You have great construction experience, but I noticed an opportunity: ${observation}.\n\n` +
  `We help independent builders upgrade their static websites into active quotation engines — complete with 3D elevations, 360° project walkthroughs, and a 24/7 WhatsApp AI agent that pre-qualifies plot details and budgets.\n\n` +
  `Would you mind if I shared 3 specific improvement concepts for your site?`;

const emailSubject = `3 website & quotation enquiry improvements for ${name}`;
const emailBody = 
  `Hi ${name} Team,\n\n` +
  `I came across your construction business while researching turnkey house contractors in ${location} and reviewed your website (${lead.rawWebsite}).\n\n` +
  `Your completed projects show solid construction quality, but ${observation}.\n\n` +
  `Today's homeowners want to explore completed homes in 360°, check package estimates per sq.ft, and reach out via WhatsApp immediately.\n\n` +
  `Would you be open to a quick 3-point audit showing how to convert more website visitors into booked site consultations?\n\n` +
  `Best regards,\nSuresh Kumar\nBuilder Digital Experience & Enquiry System™`;

return [{
  json: {
    ...lead,
    segment: isError ? "Segment B - Site Down/Error" : "Segment B - Website Modernization",
    whatsappMessage,
    emailSubject,
    emailBody
  }
}];

// Anti-Ban Jitter Generator
// Randomized delay between 45 to 80 seconds so message intervals look organic and human
const minSeconds = 45;
const maxSeconds = 80;
const jitterDelay = Math.floor(Math.random() * (maxSeconds - minSeconds + 1)) + minSeconds;

return [{
  json: {
    jitterDelaySeconds: jitterDelay
  }
}];
